export async function profile(db, cache, tenantId, userId) {
 const key = userId;
 if (cache.has(key)) return cache.get(key);
 const row = await db.query('SELECT * FROM profiles WHERE user_id = ?', [userId]);
 cache.set(key, row);
 return row;
}

